    #[requires(!label.is_empty())]
    #[ensures(ret.as_ref().is_ok_and(|id| id.object_kind() == crate::model::SemanticObjectKind::Referent) || ret.is_err())]
    fn build_elided_referent_with_sort_and_source(
        &mut self,
        label: String,
        sort: SemanticSort,
        source: Option<crate::model::SemanticSource>,
    ) -> Result<SemanticObjectId, SemanticsError> {
        let id = self.next_referent_with_sort_id(sort);
        self.insert(
            id,
            SemanticObject::referent(
                ReferentCategory::Constant,
                sort,
                None,
                Some(new!(Descriptor {
                    kind: DescriptorKind::Elided,
                    word: label,
                    speaker: None,
                    body: None,
                    veridical: None,
                    relative_clauses: Vec::new(),
                    quantity: None,
                    name: None,
                    scale: None,
                    definiteness: None,
                    operand: None,
                })),
                None,
                source,
                Vec::new(),
            ),
        )?;
        Ok(id)
    }

    #[requires(!word.is_empty())]
    #[requires(crate::model::argument_object_kind_can_fill(operand.object_kind()))]
    #[ensures(ret.as_ref().is_ok_and(|id| id.object_kind() == crate::model::SemanticObjectKind::Referent) || ret.is_err())]
    fn build_generated_abstraction_about_referent(
        &mut self,
        word: &str,
        operand: SemanticObjectId,
        source: Option<crate::model::SemanticSource>,
    ) -> Result<SemanticObjectId, SemanticsError> {
        let id = self.next_referent_with_sort_id(SemanticSort::eventuality());
        self.insert(
            id,
            SemanticObject::referent(
                ReferentCategory::Constant,
                SemanticSort::eventuality(),
                None,
                Some(new!(Descriptor {
                    kind: DescriptorKind::AbstractionAbout,
                    word: word.to_owned(),
                    speaker: Some(self.current_speaker()),
                    body: None,
                    veridical: None,
                    relative_clauses: Vec::new(),
                    quantity: None,
                    name: None,
                    scale: None,
                    definiteness: None,
                    operand: Some(operand),
                })),
                None,
                source,
                Vec::new(),
            ),
        )?;
        Ok(id)
    }

    #[requires(id.object_kind() == object.object_kind())]
    #[ensures(true)]
    fn insert(
        &mut self,
        id: SemanticObjectId,
        mut object: SemanticObject,
    ) -> Result<(), SemanticsError> {
        if object.object_kind() == crate::model::SemanticObjectKind::Predication
            && let Some(eventuality) = object.eventuality
        {
            for modal_argument in &mut object.modal_arguments {
                self.bind_generated_modal_argument_to_host_event(modal_argument, eventuality);
            }
            self.finalize_generated_eventuality_for_predication_mode(eventuality, object.mode)?;
        }
        if self.objects.insert(id, object).is_some() {
            return Err(SemanticsError {
                kind: SemanticsErrorKind::DuplicateObject,
                message: format!("semantic builder attempted to insert duplicate object ID {id}"),
            });
        }
        Ok(())
    }

    #[requires(eventuality.referent_sort().is_some_and(|sort| sort.is_subsort_of(SemanticSort::eventuality())))]
    #[ensures(true)]
    fn finalize_generated_eventuality_for_predication_mode(
        &mut self,
        eventuality: SemanticObjectId,
        mode: Option<PredicationMode>,
    ) -> Result<(), SemanticsError> {
        let story_time = self.options.story_time;
        let story_anchor = self.story_time_anchor;
        let mut advance_story_time = false;
        {
            let event = self.objects.get_mut(&eventuality).ok_or_else(|| {
                invalid_graph(format!("missing generated eventuality {eventuality}"))
            })?;
            if mode != Some(PredicationMode::Asserted) {
                clear_generated_inherited_event_time_path(event);
                clear_generated_inherited_event_space_path(event);
                return Ok(());
            }
            let explicit_temporal = generated_event_has_explicit_temporal_marker(event);
            let sticky_temporal = generated_event_has_explicit_sticky_temporal_marker(event);
            if story_time {
                if let Some(anchor) = story_anchor
                    && !explicit_temporal
                {
                    clear_generated_event_time_path(event);
                    event.time = Some(new!(AnchorRelation {
                        relation: "after".to_owned(),
                        anchor,
                        sticky: false,
                        inherited: None,
                        distance: None,
                        magnitude: None,
                        scalar_negation: None,
                        motion: None,
                    }));
                }
                advance_story_time =
                    !explicit_temporal || sticky_temporal || story_anchor.is_none();
            }
        }
        if advance_story_time {
            self.story_time_anchor = Some(eventuality);
        }
        Ok(())
    }

    #[requires(true)]
    #[ensures(true)]
    fn set_semantic_object_source(
        &mut self,
        id: SemanticObjectId,
        source: Option<crate::model::SemanticSource>,
    ) -> Result<(), SemanticsError> {
        let object = self
            .objects
            .get_mut(&id)
            .ok_or_else(|| invalid_graph(format!("missing generated semantic object {id}")))?;
        object.source = source;
        Ok(())
    }

