#[requires(true)]
#[ensures(ret.is_ok() || ret.is_err())]
fn generated_nonlogical_composition_operator(
    connective: &RelationAfterthoughtConnectiveSyntax,
) -> Result<CompositionOperator, SemanticsError> {
    match generated_relation_afterthought_connective_primary_cmavo(connective) {
        Some(Cmavo::Johu) => Ok(CompositionOperator::Joint),
        Some(Cmavo::Joi) => Ok(CompositionOperator::Mass),
        Some(Cmavo::Ce) => Ok(CompositionOperator::Set),
        Some(Cmavo::Ceho) => Ok(CompositionOperator::Sequence),
        Some(Cmavo::Fahu) => Ok(CompositionOperator::Respectively),
        Some(Cmavo::Johe) => Ok(CompositionOperator::Union),
        Some(Cmavo::Kuha) => Ok(CompositionOperator::Intersection),
        Some(Cmavo::Pihu) => Ok(CompositionOperator::CrossProduct),
        Some(Cmavo::Bihi) => Ok(CompositionOperator::UnorderedInterval),
        Some(Cmavo::Biho) => Ok(CompositionOperator::OrderedInterval),
        Some(Cmavo::Mihi) => Ok(CompositionOperator::CenteredInterval),
        _ => Err(unsupported(&format!(
            "unsupported nonlogical relation connective {}",
            generated_relation_afterthought_connective_source(connective)?
        ))),
    }
}

#[requires(true)]
#[ensures(!ret || generated_relation_afterthought_connective_has_se(connective))]
fn generated_relation_afterthought_connective_reverses_composition_members(
    connective: &RelationAfterthoughtConnectiveSyntax,
) -> bool {
    generated_relation_afterthought_connective_has_se(connective)
        && matches!(
            generated_relation_afterthought_connective_primary_cmavo(connective),
            Some(Cmavo::Ceho | Cmavo::Fahu | Cmavo::Pihu | Cmavo::Biho | Cmavo::Mihi)
        )
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn generated_guhek_connective_source(connective: &GuhekConnectiveSyntax) -> String {
    let mut tokens = Vec::new();
    if let Some(token) = &connective.nahe {
        tokens.push(token);
    }
    if let Some(token) = &connective.se {
        tokens.push(token);
    }
    tokens.push(&connective.guha.value);
    if let Some(token) = &connective.nai {
        tokens.push(&token.value);
    }
    connective_source_from_tokens(tokens)
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn generated_guhek_gik_connective_source(
    guhek: &GuhekConnectiveSyntax,
    gik: &GikConnectiveSyntax,
) -> String {
    let mut parts = vec![
        generated_guhek_connective_source(guhek),
        token_text(&gik.gi.value),
    ];
    if let Some(nai) = &gik.nai {
        parts.push(token_text(&nai.value));
    }
    parts.join(" ")
}

#[requires(true)]
#[ensures(true)]
fn generated_guhek_connective_formula_operator(
    connective: &GuhekConnectiveSyntax,
) -> FormulaOperator {
    match connective.guha.value.cmavo() {
        Some(Cmavo::Guha) => FormulaOperator::Or,
        Some(Cmavo::Guhe) => FormulaOperator::And,
        Some(Cmavo::Guho) => FormulaOperator::Iff,
        Some(Cmavo::Guhu) => FormulaOperator::WhetherOrNot,
        _ => FormulaOperator::And,
    }
}

#[requires(true)]
#[ensures(true)]
fn generated_guhek_connective_has_se(connective: &GuhekConnectiveSyntax) -> bool {
    connective.se.is_some()
}

#[requires(true)]
#[ensures(true)]
fn generated_guhek_connective_negates_left(connective: &GuhekConnectiveSyntax) -> bool {
    connective.nai.is_some()
}

#[requires(true)]
#[ensures(true)]
fn generated_gik_connective_negates_right(connective: &GikConnectiveSyntax) -> bool {
    connective.nai.is_some()
}

#[requires(true)]
#[ensures(ret.is_none() || ret.as_ref().is_some_and(|table| table.len() == 4))]
fn generated_guhek_gik_connective_truth_table(
    guhek: &GuhekConnectiveSyntax,
    gik: &GikConnectiveSyntax,
) -> Option<String> {
    generated_guhek_connective_truth_table_with_negations(
        guhek,
        generated_guhek_connective_negates_left(guhek),
        generated_gik_connective_negates_right(gik),
    )
}

#[requires(true)]
#[ensures(ret.is_none() || ret.as_ref().is_some_and(|table| table.len() == 4))]
fn generated_guhek_connective_truth_table_with_negations(
    guhek: &GuhekConnectiveSyntax,
    left_negated: bool,
    right_negated: bool,
) -> Option<String> {
    let operator = generated_guhek_connective_formula_operator(guhek);
    let se = generated_guhek_connective_has_se(guhek);
    Some(
        [(true, true), (true, false), (false, true), (false, false)]
            .into_iter()
            .map(|(left, right)| {
                let left = if left_negated { !left } else { left };
                let right = if right_negated { !right } else { right };
                let result = if se {
                    connective_truth_value_for_operator(operator, right, left)
                } else {
                    connective_truth_value_for_operator(operator, left, right)
                };
                if result { 'T' } else { 'F' }
            })
            .collect(),
    )
}

#[requires(matches!(
    operator,
    FormulaOperator::And
        | FormulaOperator::Or
        | FormulaOperator::Iff
        | FormulaOperator::WhetherOrNot
))]
#[ensures(true)]
fn connective_truth_value_for_operator(operator: FormulaOperator, left: bool, right: bool) -> bool {
    match operator {
        FormulaOperator::And => left && right,
        FormulaOperator::Or => left || right,
        FormulaOperator::Iff => left == right,
        FormulaOperator::WhetherOrNot => left,
        _ => unreachable!("precondition restricts connective truth operators"),
    }
}

#[requires(matches!(
    operator,
    FormulaOperator::And
        | FormulaOperator::Or
        | FormulaOperator::Iff
        | FormulaOperator::WhetherOrNot
))]
#[ensures(ret.len() == 4)]
fn generated_truth_table_for_formula_operator(operator: FormulaOperator) -> String {
    [(true, true), (true, false), (false, true), (false, false)]
        .into_iter()
        .map(|(left, right)| {
            if connective_truth_value_for_operator(operator, left, right) {
                'T'
            } else {
                'F'
            }
        })
        .collect()
}

#[requires(true)]
#[ensures(ret == (id.object_kind() == crate::model::SemanticObjectKind::Referent && id.referent_sort().is_some_and(|sort| sort.is_subsort_of(SemanticSort::eventuality()))))]
fn semantic_id_is_eventuality(id: SemanticObjectId) -> bool {
    id.object_kind() == crate::model::SemanticObjectKind::Referent
        && id
            .referent_sort()
            .is_some_and(|sort| sort.is_subsort_of(SemanticSort::eventuality()))
}

#[requires(true)]
#[ensures(ret == (object.object_type == crate::model::SemanticObjectKind::Referent && object.sort.is_some_and(|sort| sort.is_subsort_of(SemanticSort::eventuality()))))]
fn generated_semantic_object_is_eventuality(object: &SemanticObject) -> bool {
    object.object_type == crate::model::SemanticObjectKind::Referent
        && object
            .sort
            .is_some_and(|sort| sort.is_subsort_of(SemanticSort::eventuality()))
}

#[requires(true)]
#[ensures(true)]
fn referent_qualifier_kind(cmavo: Option<Cmavo>) -> DescriptorKind {
    match cmavo {
        Some(Cmavo::Lahe) => DescriptorKind::ReferentOfSymbol,
        Some(Cmavo::Luhe) => DescriptorKind::SymbolForReferent,
        Some(Cmavo::Tuha) => DescriptorKind::AbstractionAbout,
        Some(Cmavo::Luha) => DescriptorKind::MemberOf,
        Some(Cmavo::Luhi) => DescriptorKind::SetFrom,
        Some(Cmavo::Luho) => DescriptorKind::MassFrom,
        Some(Cmavo::Vuhi) => DescriptorKind::SequenceFrom,
        _ => DescriptorKind::QualifiedSumti,
    }
}

#[requires(true)]
#[ensures(true)]
fn referent_qualifier_sort(cmavo: Option<Cmavo>) -> SemanticSort {
    match cmavo {
        Some(Cmavo::Luhe) => SemanticSort::Sign,
        Some(Cmavo::Tuha) => SemanticSort::eventuality(),
        Some(Cmavo::Luhi) => SemanticSort::Set,
        Some(Cmavo::Luho) => SemanticSort::Mass,
        Some(Cmavo::Vuhi) => SemanticSort::Sequence,
        _ => SemanticSort::Entity,
    }
}

#[requires(!tokens.is_empty())]
#[ensures(true)]
fn simple_pa_integer_from_tokens(tokens: &[Token]) -> Option<i64> {
    let mut value = 0i64;
    for token in tokens {
        value = value.checked_mul(10)?;
        value = value.checked_add(pa_digit_value(token.cmavo()?)?)?;
    }
    Some(value)
}

#[requires(!tokens.is_empty())]
#[requires(!text.is_empty())]
#[ensures(true)]
fn parse_generated_recurrence_integer(tokens: &[Token], text: &str) -> Option<i64> {
    parse_generated_relational_pa_integer(text).or_else(|| simple_pa_integer_from_tokens(tokens))
}

#[requires(!text.is_empty())]
#[ensures(true)]
fn parse_generated_relational_pa_integer(text: &str) -> Option<i64> {
    let (prefix, rest) = text.split_once(char::is_whitespace)?;
    if !matches!(prefix, "su'o" | "su'e" | "za'u" | "me'i" | "su'a") {
        return None;
    }
    let rest = rest.trim();
    if rest.is_empty() {
        return None;
    }
    parse_generated_simple_pa_integer(rest)
}

#[requires(!text.is_empty())]
#[ensures(true)]
fn parse_generated_simple_pa_integer(text: &str) -> Option<i64> {
    let mut words = text.split_whitespace();
    let first = words.next()?;
    let (sign, first_digit) = match first {
        "ni'u" => (-1_i64, words.next()?),
        "ma'u" => (1_i64, words.next()?),
        _ => (1_i64, first),
    };
    let mut value = i64::from(pa_digit_value_for_text(first_digit)?);
    for word in words {
        let digit = i64::from(pa_digit_value_for_text(word)?);
        value = value.checked_mul(10)?.checked_add(digit)?;
    }
    Some(sign * value)
}

#[requires(!word.is_empty())]
#[ensures(ret.is_none_or(|digit| digit <= 9))]
fn pa_digit_value_for_text(word: &str) -> Option<u8> {
    match word {
        "no" => Some(0),
        "pa" => Some(1),
        "re" => Some(2),
        "ci" => Some(3),
        "vo" => Some(4),
        "mu" => Some(5),
        "xa" => Some(6),
        "ze" => Some(7),
        "bi" => Some(8),
        "so" => Some(9),
        _ => None,
    }
}

#[requires(true)]
#[ensures(ret.is_none_or(|digit| (0..=9).contains(&digit)))]
fn pa_digit_value(cmavo: Cmavo) -> Option<i64> {
    match cmavo {
        Cmavo::No => Some(0),
        Cmavo::Pa => Some(1),
        Cmavo::Re => Some(2),
        Cmavo::Ci => Some(3),
        Cmavo::Vo => Some(4),
        Cmavo::Mu => Some(5),
        Cmavo::Xa => Some(6),
        Cmavo::Ze => Some(7),
        Cmavo::Bi => Some(8),
        Cmavo::So => Some(9),
        _ => None,
    }
}

#[requires(!text.is_empty())]
#[ensures(true)]
fn math_literal_for_pa_text(text: String) -> MathLiteral {
    if let Some(components) = parse_generated_mixed_radix_pa_components(&text) {
        return MathLiteral::mixed_radix(components);
    }
    parse_generated_simple_pa_integer(&text)
        .map(MathLiteral::integer)
        .or_else(|| {
            parse_generated_simple_pa_decimal(&text)
                .map(|decimal| MathLiteral::text(MathLiteralKind::Decimal, decimal))
        })
        .unwrap_or_else(|| MathLiteral::text(MathLiteralKind::Number, text))
}

#[requires(!text.is_empty())]
#[ensures(ret.as_ref().is_none_or(|components| components.len() >= 2))]
fn parse_generated_mixed_radix_pa_components(text: &str) -> Option<Vec<MixedRadixComponent>> {
    let words = text.split_whitespace().collect::<Vec<_>>();
    if !words.contains(&"pi'e") {
        return None;
    }
    let mut components = Vec::new();
    let mut current = Vec::new();
    for word in words {
        if word == "pi'e" {
            if current.is_empty() {
                return None;
            }
            let component_text = current.join(" ");
            components.push(MixedRadixComponent::new(
                component_text.clone(),
                parse_generated_simple_pa_integer(&component_text),
            ));
            current.clear();
        } else {
            current.push(word);
        }
    }
    if current.is_empty() {
        return None;
    }
    let component_text = current.join(" ");
    components.push(MixedRadixComponent::new(
        component_text.clone(),
        parse_generated_simple_pa_integer(&component_text),
    ));
    (components.len() >= 2).then_some(components)
}

#[requires(!text.is_empty())]
#[ensures(ret.as_ref().is_none_or(|value| !value.is_empty()))]
fn parse_generated_simple_pa_decimal(text: &str) -> Option<String> {
    let words = text.split_whitespace().collect::<Vec<_>>();
    let (sign, words) = match words.as_slice() {
        ["ni'u", rest @ ..] => ("-", rest),
        ["ma'u", rest @ ..] => ("", rest),
        _ => ("", words.as_slice()),
    };
    let point = words.iter().position(|word| *word == "pi")?;
    if words[point + 1..].is_empty() {
        return None;
    }
    let integer = if point == 0 {
        "0".to_owned()
    } else {
        words[..point]
            .iter()
            .map(|word| pa_digit_value_for_text(word).map(|digit| char::from(b'0' + digit)))
            .collect::<Option<String>>()?
    };
    let fraction = words[point + 1..]
        .iter()
        .map(|word| pa_digit_value_for_text(word).map(|digit| char::from(b'0' + digit)))
        .collect::<Option<String>>()?;
    Some(format!("{sign}{integer}.{fraction}"))
}

#[requires(true)]
#[ensures(tokens.is_empty() || !ret.is_empty())]
fn letteral_units_for_tokens(tokens: &[Token]) -> Vec<LetteralUnit> {
    let mut units = Vec::new();
    let mut index = 0;
    while index < tokens.len() {
        match token_cmavo(&tokens[index]) {
            Some(Cmavo::Tei) => {
                if let Some(relative_end) = tokens[index + 1..]
                    .iter()
                    .position(|token| token_cmavo(token) == Some(Cmavo::Foi))
                {
                    let end = index + 1 + relative_end;
                    let inner = letteral_units_for_tokens(&tokens[index + 1..end]);
                    if !inner.is_empty() {
                        let source_words = letteral_source_words_for_tokens(&tokens[index..=end]);
                        let value = letteral_unit_values_joined(&inner);
                        units.push(LetteralUnit::compound(source_words, value, inner));
                        index = end + 1;
                        continue;
                    }
                }
                units.push(letteral_unit_for_token(&tokens[index]));
                index += 1;
            }
            Some(Cmavo::Sehe) => {
                let source_words = letteral_source_words_for_tokens(&tokens[index..]);
                let value = if tokens[index + 1..].is_empty() {
                    None
                } else {
                    Some(
                        tokens[index + 1..]
                            .iter()
                            .map(token_text)
                            .collect::<Vec<_>>()
                            .join(""),
                    )
                };
                units.push(LetteralUnit::simple(
                    LetteralUnitKind::CharacterCode,
                    source_words,
                    Some(token_list_text(tokens[index..].iter())),
                    value,
                    None,
                    None,
                ));
                break;
            }
            Some(Cmavo::Tau | Cmavo::Zai | Cmavo::Ceha) if index + 1 < tokens.len() => {
                let marker = token_text(&tokens[index]);
                let next = &tokens[index + 1];
                units.push(LetteralUnit::simple(
                    LetteralUnitKind::Shift,
                    letteral_source_words_for_tokens(&tokens[index..=index + 1]),
                    Some(format!("{marker} {}", token_text(next))),
                    Some(token_text(next)),
                    letteral_shift_modifier(&tokens[index]),
                    None,
                ));
                index += 2;
            }
            Some(
                Cmavo::Gahe
                | Cmavo::Toha
                | Cmavo::Naha
                | Cmavo::Loha
                | Cmavo::Geho
                | Cmavo::Jeho
                | Cmavo::Joho
                | Cmavo::Ruho,
            ) => {
                units.push(LetteralUnit::simple(
                    LetteralUnitKind::Shift,
                    letteral_source_words_for_token(&tokens[index]),
                    Some(token_text(&tokens[index])),
                    None,
                    letteral_shift_modifier(&tokens[index]),
                    None,
                ));
                index += 1;
            }
            _ => {
                units.push(letteral_unit_for_token(&tokens[index]));
                index += 1;
            }
        }
    }
    units
}

#[requires(true)]
#[ensures(!ret.source_words.is_empty())]
fn letteral_unit_for_token(token: &Token) -> LetteralUnit {
    let source_words = letteral_source_words_for_token(token);
    let source_text = token_text(token);
    let bu_depth = letteral_bu_depth(token.core_word());
    let value = basic_letteral_value(&source_words);
    let kind = if parse_generated_simple_pa_integer(&source_text).is_some() && bu_depth == 0 {
        LetteralUnitKind::Digit
    } else {
        LetteralUnitKind::Glyph
    };
    LetteralUnit::simple(
        kind,
        source_words,
        Some(source_text),
        value,
        None,
        (bu_depth > 0).then_some(bu_depth),
    )
}

#[requires(true)]
#[ensures(true)]
fn letteral_shift_modifier(token: &Token) -> Option<String> {
    let modifier = match token_cmavo(token)? {
        Cmavo::Gahe => "upperCase",
        Cmavo::Toha => "lowerCase",
        Cmavo::Tau => "singleCaseShift",
        Cmavo::Zai => "script",
        Cmavo::Ceha => "font",
        Cmavo::Naha => "cancel",
        Cmavo::Loha => "lojbanScript",
        Cmavo::Geho => "greekScript",
        Cmavo::Jeho => "hebrewScript",
        Cmavo::Joho => "arabicScript",
        Cmavo::Ruho => "cyrillicScript",
        _ => return None,
    };
    Some(modifier.to_owned())
}

#[requires(true)]
#[ensures(tokens.is_empty() || !ret.is_empty())]
fn letteral_source_words_for_tokens(tokens: &[Token]) -> Vec<String> {
    let mut words = Vec::new();
    for token in tokens {
        words.extend(letteral_source_words_for_token(token));
    }
    words
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn letteral_source_words_for_token(token: &Token) -> Vec<String> {
    let mut words = Vec::new();
    letteral_source_words_for_word_like(token.core_word(), &mut words);
    if words.is_empty() {
        words.push(token_text(token));
    }
    words
}

#[requires(true)]
#[ensures(true)]
fn letteral_source_words_for_word_like(word_like: &WordLike, out: &mut Vec<String>) {
    match word_like.as_data() {
        data!(WordLike::PlainWord(word)) => out.push(word_text(word)),
        data!(WordLike::LerfuWord { base, bu }) => {
            letteral_source_words_for_word_like(base, out);
            out.push(word_text(bu));
        }
        _ => out.push(word_like.to_string()),
    }
}

#[requires(true)]
#[ensures(true)]
fn token_cmavo(token: &Token) -> Option<Cmavo> {
    token.core_word().bare_word().and_then(Word::cmavo)
}

#[requires(true)]
#[ensures(true)]
fn letteral_bu_depth(word_like: &WordLike) -> usize {
    match word_like.as_data() {
        data!(WordLike::LerfuWord { base, .. }) => 1 + letteral_bu_depth(base),
        _ => 0,
    }
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|value| !value.is_empty()))]
fn basic_letteral_value(source_words: &[String]) -> Option<String> {
    match source_words {
        [word] => basic_letteral_word_value(word).or_else(|| {
            parse_generated_simple_pa_integer(word)
                .filter(|value| (0..=9).contains(value))
                .map(|value| value.to_string())
        }),
        [base, bu] if bu == "bu" => match base.as_str() {
            "ky" => Some("q".to_owned()),
            "vy" => Some("w".to_owned()),
            "y'y" => Some("h".to_owned()),
            "a" | "e" | "i" | "o" | "u" | "y" => Some(base.clone()),
            _ => basic_letteral_word_value(base),
        },
        _ => None,
    }
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|value| !value.is_empty()))]
fn basic_letteral_word_value(word: &str) -> Option<String> {
    let value = match word {
        "by" => "b",
        "cy" => "c",
        "dy" => "d",
        "fy" => "f",
        "gy" => "g",
        "jy" => "j",
        "ky" => "k",
        "ly" => "l",
        "my" => "m",
        "ny" => "n",
        "py" => "p",
        "ry" => "r",
        "sy" => "s",
        "ty" => "t",
        "vy" => "v",
        "xy" => "x",
        "zy" => "z",
        "y'y" => "'",
        _ => return None,
    };
    Some(value.to_owned())
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|value| !value.is_empty()))]
fn letteral_unit_values_joined(units: &[LetteralUnit]) -> Option<String> {
    let mut value = String::new();
    for unit in units {
        value.push_str(unit.value.as_ref()?);
    }
    Some(value)
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|value| !value.is_empty()))]
fn letteral_display_text(units: &[LetteralUnit]) -> Option<String> {
    if units.iter().all(|unit| {
        matches!(unit.kind, LetteralUnitKind::Glyph | LetteralUnitKind::Digit)
            && unit.value.is_some()
    }) {
        letteral_unit_values_joined(units)
    } else {
        None
    }
}

#[requires(!text.is_empty())]
#[ensures(true)]
fn quantity_form_for_text(text: &str) -> QuantityForm {
    match text {
        "ro" => QuantityForm::All,
        text if text.starts_with("su'o") => QuantityForm::AtLeast,
        text if text.starts_with("su'e") => QuantityForm::AtMost,
        text if text.starts_with("za'u") => QuantityForm::MoreThan,
        text if text.starts_with("me'i") => QuantityForm::LessThan,
        text if text.starts_with("ji'i") => QuantityForm::Approximate,
        "so'a" => QuantityForm::TooFew,
        "so'e" => QuantityForm::Enough,
        "so'i" | "so'o" | "so'u" => QuantityForm::Indefinite,
        "du'e" => QuantityForm::TooMany,
        _ => QuantityForm::Exact,
    }
}

#[requires(true)]
#[ensures(true)]
fn quantity_form_for_value(value: &QuantityValue) -> QuantityForm {
    value
        .text
        .as_deref()
        .map(quantity_form_for_text)
        .unwrap_or(QuantityForm::Exact)
}

#[requires(true)]
#[ensures(true)]
fn generated_quantifier_formula_operator(quantifier: &QuantifierSyntax) -> FormulaOperator {
    match token_list_text(quantifier_tokens(quantifier).iter()).as_str() {
        "ro" => FormulaOperator::Forall,
        "no" => FormulaOperator::None,
        _ => FormulaOperator::Cardinality,
    }
}

#[requires(true)]
#[ensures(true)]
fn quantifier_tokens(quantifier: &QuantifierSyntax) -> Vec<Token> {
    let mut visitor = GeneratedSpanCollector::default();
    quantifier.visit_in_order(&mut visitor);
    visitor.tokens
}

#[requires(true)]
#[ensures(source_text.is_none() -> ret.as_slice() == spans)]
fn source_spans_with_following_cmevla_period(
    spans: &[SourceSpan],
    source_text: Option<&str>,
) -> Vec<SourceSpan> {
    let Some(source_text) = source_text else {
        return spans.to_vec();
    };
    let Some((last_index, last_span)) = spans
        .iter()
        .enumerate()
        .max_by_key(|(_, span)| span.byte_end)
    else {
        return Vec::new();
    };
    let Some(period) = source_text
        .get(last_span.byte_end..)
        .and_then(|tail| tail.chars().next())
        .filter(|period| is_lojban_period(*period))
    else {
        return spans.to_vec();
    };
    let Ok(expanded) = SourceSpan::new(
        last_span.source_id.clone(),
        last_span.byte_start,
        last_span.byte_end + period.len_utf8(),
        last_span.char_start,
        last_span.char_end + 1,
    ) else {
        return spans.to_vec();
    };
    let mut expanded_spans = spans.to_vec();
    expanded_spans[last_index] = expanded;
    expanded_spans
}

#[requires(true)]
#[ensures(ret == matches!(value, '.' | 'ӏ' | 'Ӏ' | '\u{ed89}'))]
fn is_lojban_period(value: char) -> bool {
    matches!(value, '.' | 'ӏ' | 'Ӏ' | '\u{ed89}')
}

#[requires(true)]
#[ensures(true)]
fn token_list_text<'a>(tokens: impl Iterator<Item = &'a Token>) -> String {
    tokens.map(token_text).collect::<Vec<_>>().join(" ")
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|text| !text.is_empty()))]
fn non_empty_token_list_text<'a>(tokens: impl Iterator<Item = &'a Token>) -> Option<String> {
    let text = token_list_text(tokens);
    if text.is_empty() { None } else { Some(text) }
}

#[requires(true)]
#[ensures(ret.as_ref().is_ok_and(|text| !text.is_empty()) || ret.is_err())]
fn generated_selbri_surface_text(selbri: &SelbriSyntax) -> Result<String, SemanticsError> {
    let mut visitor = GeneratedSpanCollector::default();
    selbri.visit_in_order(&mut visitor);
    non_empty_token_list_text(visitor.tokens.iter())
        .map_or_else(|| relation_label_from_selbri(selbri), Ok)
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn generated_vocative_kind_for_markers(
    markers: &WithFreeModifiers<VocativeMarkerWordsSyntax, FreeModifierSyntax>,
) -> String {
    let first = generated_vocative_marker_first_token(&markers.value);
    match first.cmavo() {
        Some(Cmavo::Coi) => "greeting".to_owned(),
        Some(Cmavo::Jehe) => "acknowledgement".to_owned(),
        Some(Cmavo::Coho) => "farewell".to_owned(),
        Some(Cmavo::Fihi) => "welcome".to_owned(),
        Some(Cmavo::Mihe) => "selfIdentification".to_owned(),
        Some(Cmavo::Doi) => "address".to_owned(),
        _ => token_text(first),
    }
}

#[requires(true)]
#[ensures(!token_text(ret).is_empty())]
fn generated_vocative_marker_first_token(markers: &VocativeMarkerWordsSyntax) -> &Token {
    match markers {
        VocativeMarkerWordsSyntax::CoiVocativeMarkerWords(markers) => &markers.first_coi,
        VocativeMarkerWordsSyntax::DoiVocativeMarkerWords(markers) => &markers.0,
    }
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|definition| crate::model::argument_object_kind_can_fill(definition.value.object_kind())))]
fn scalar_scale_definition_for_modal_argument(
    modal_argument: &ModalArgument,
) -> Option<GeneratedScalarScaleDefinition> {
    modal_argument.relation.as_ref()?;
    if modal_argument.introduced_by != "ci'u" {
        return None;
    }
    let value = modal_argument.arguments.get(&argument_key(1))?.value?;
    Some(GeneratedScalarScaleDefinition::from_data(data!(
        GeneratedScalarScaleDefinition {
            value,
            introduced_by: modal_argument.introduced_by.clone(),
            source: modal_argument.source.clone(),
        }
    )))
}

#[requires(true)]
#[ensures(ret.construct.as_deref() == Some("scalar-scale"))]
fn source_as_scalar_scale(source: crate::model::SemanticSource) -> crate::model::SemanticSource {
    crate::model::SemanticSource {
        construct: Some("scalar-scale".to_owned()),
        ..source
    }
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|source| source.construct.as_deref() == Some("name-denotation")))]
fn source_as_name_denotation(
    source: Option<crate::model::SemanticSource>,
) -> Option<crate::model::SemanticSource> {
    source.map(|source| crate::model::SemanticSource {
        construct: Some("name-denotation".to_owned()),
        ..source
    })
}

#[requires(!construct.is_empty())]
#[ensures(ret.as_ref().is_none_or(|source| source.construct.as_deref() == Some(construct)))]
fn source_with_construct(
    source: Option<crate::model::SemanticSource>,
    construct: &str,
) -> Option<crate::model::SemanticSource> {
    source.map(|source| crate::model::SemanticSource {
        construct: Some(construct.to_owned()),
        ..source
    })
}

#[requires(true)]
#[ensures(!ret.introduced_by.is_empty())]
fn scalar_negation_for_marker<F>(marker: &WithFreeModifiers<Token, F>) -> ScalarNegation {
    scalar_negation_for_token(&marker.value)
}

#[requires(true)]
#[ensures(!ret.introduced_by.is_empty())]
fn scalar_negation_for_token(token: &Token) -> ScalarNegation {
    ScalarNegation::new(
        scalar_negation_kind_for_cmavo(token.cmavo()),
        token_text(token),
    )
}

#[requires(true)]
#[ensures(true)]
fn scalar_negation_kind_for_cmavo(cmavo: Option<Cmavo>) -> ScalarNegationKind {
    match cmavo {
        Some(Cmavo::Tohe) => ScalarNegationKind::Opposite,
        Some(Cmavo::Nohe) => ScalarNegationKind::Neutral,
        Some(Cmavo::Jeha) => ScalarNegationKind::Affirmed,
        _ => ScalarNegationKind::OtherThan,
    }
}

#[requires(true)]
#[ensures(true)]
fn scalar_negated_sumti_qualifier_kind(cmavo: Option<Cmavo>) -> DescriptorKind {
    match cmavo {
        Some(Cmavo::Tohe) => DescriptorKind::OppositeOf,
        Some(Cmavo::Nohe) => DescriptorKind::NeutralOf,
        Some(Cmavo::Jeha) => DescriptorKind::AffirmedAs,
        _ => DescriptorKind::OtherThan,
    }
}

#[requires(true)]
#[ensures(true)]
fn descriptor_definiteness_for_scalar_negated_sumti(
    cmavo: Option<Cmavo>,
) -> Option<DescriptorDefiniteness> {
    match cmavo {
        Some(Cmavo::Tohe) => Some(DescriptorDefiniteness::UniqueExtreme),
        Some(Cmavo::Nohe) => Some(DescriptorDefiniteness::NeutralPoint),
        Some(Cmavo::Jeha) => Some(DescriptorDefiniteness::AffirmedPoint),
        _ => Some(DescriptorDefiniteness::IndefiniteAlternative),
    }
}

#[requires(eventuality.referent_sort().is_some_and(|sort| sort.is_subsort_of(SemanticSort::eventuality())))]
#[ensures(true)]
fn bind_generated_modal_argument_to_host_event(
    modal_argument: &mut ModalArgument,
    eventuality: SemanticObjectId,
) {
    let _ =
        bind_generated_modal_argument_to_host_event_preserving_elision(modal_argument, eventuality);
}

#[requires(eventuality.referent_sort().is_some_and(|sort| sort.is_subsort_of(SemanticSort::eventuality())))]
#[ensures(ret.as_ref().is_none_or(|elision| elision.argument.kind == ArgumentValueKind::Elided))]
fn bind_generated_modal_argument_to_host_event_preserving_elision(
    modal_argument: &mut ModalArgument,
    eventuality: SemanticObjectId,
) -> Option<GeneratedHostEventModalElision> {
    if modal_argument.relation.is_none() {
        return None;
    }
    let relation = modal_argument.relation.as_ref()?.clone();
    let Some(place) = generated_modal_relation_host_event_place_for_argument(modal_argument) else {
        return None;
    };
    let key = argument_key(place);
    if modal_argument
        .arguments
        .get(&key)
        .is_some_and(|argument| argument.kind != ArgumentValueKind::Elided)
    {
        return None;
    }
    let original_elision = modal_argument.arguments.get(&key).cloned();
    let mut data = modal_argument.clone().into_data();
    data.arguments
        .insert(key.clone(), ArgumentValue::filled(eventuality, None));
    *modal_argument = ModalArgument::from_data(data);
    original_elision.map(|argument| {
        new!(GeneratedHostEventModalElision {
            relation,
            introduced_by: modal_argument.introduced_by.clone(),
            source: modal_argument.source.clone(),
            place,
            argument,
        })
    })
}

#[requires(true)]
#[ensures(ret.is_none_or(|place| place > 0))]
fn generated_modal_relation_host_event_place_for_argument(
    modal_argument: &ModalArgument,
) -> Option<usize> {
    let relation = modal_argument.relation.as_deref()?;
    if generated_modal_relation_has_complementary_event_places(relation)
        && generated_modal_argument_place_is_filled(modal_argument, 2)
        && !generated_modal_argument_place_is_filled(modal_argument, 1)
    {
        return Some(1);
    }
    generated_modal_relation_host_event_place(relation)
}

#[requires(place > 0)]
#[ensures(true)]
fn generated_modal_argument_place_is_filled(modal_argument: &ModalArgument, place: usize) -> bool {
    modal_argument
        .arguments
        .get(&argument_key(place))
        .is_some_and(|argument| argument.kind != ArgumentValueKind::Elided)
}

#[requires(true)]
#[ensures(true)]
fn generated_modal_relation_has_complementary_event_places(relation: &str) -> bool {
    matches!(relation, "krinu" | "mukti" | "nibli" | "rinka")
}

#[requires(true)]
#[ensures(ret.is_none_or(|place| place > 0))]
fn generated_modal_relation_host_event_place(relation: &str) -> Option<usize> {
    match relation {
        "bapli" | "gasnu" | "krinu" | "mukti" | "nibli" | "rinka" => Some(2),
        "pilno" => Some(3),
        _ => None,
    }
}

#[requires(!message.is_empty())]
#[ensures(ret.kind == SemanticsErrorKind::InvalidGraph)]
fn invalid_graph(message: String) -> SemanticsError {
    SemanticsError {
        kind: SemanticsErrorKind::InvalidGraph,
        message: format!("semantic graph invariant failed: {message}"),
    }
}

#[requires(!relation.is_empty())]
#[ensures(!ret.is_empty())]
fn semantic_relation_label(relation: String) -> String {
    if relation == "du" {
        "identity".to_owned()
    } else {
        relation
    }
}

#[requires(place > 0)]
#[ensures(ret.get() == place)]
fn argument_key(place: usize) -> PlaceIndex {
    PlaceIndex::new(place)
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn token_text(token: &Token) -> String {
    token
        .core_word()
        .bare_word()
        .map(word_text)
        .unwrap_or_else(|| token.to_string())
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn quote_delimiter_text(token: &Token) -> String {
    match token.core_word().as_data() {
        data!(WordLike::DelimitedNonLojbanQuote {
            opening_delimiter,
            ..
        }) => word_text(opening_delimiter),
        data!(WordLike::DelimitedWordQuote { marker, .. }) => word_text(marker),
        _ => token_text(token),
    }
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn word_text(word: &Word) -> String {
    strip_diacritics(word.phonemes().as_str())
}

#[requires(!what.is_empty())]
#[ensures(ret.kind == SemanticsErrorKind::InvalidGraph)]
fn unsupported(what: &str) -> SemanticsError {
    SemanticsError {
        kind: SemanticsErrorKind::InvalidGraph,
        message: format!("generated semantic builder does not yet support {what}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[allow(unused_imports)]
    use bityzba::{ensures, requires};

    #[test]
    #[requires(true)]
    #[ensures(true)]
    fn token_list_text_allows_empty_token_lists_explicitly() {
        assert_eq!(token_list_text(std::iter::empty::<&Token>()), "");
        assert_eq!(
            non_empty_token_list_text(std::iter::empty::<&Token>()),
            None
        );
    }
}
